package in.agricred.loanservice;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.reactive.function.client.WebClient;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;
@RestController @RequestMapping("/api/loans") @CrossOrigin(origins="*") public class LoanController{private final LoanRepository repo;private final WebClient farmer;private final WebClient risk;private final ObjectMapper mapper=new ObjectMapper();public LoanController(LoanRepository r){repo=r;farmer=WebClient.builder().baseUrl(System.getenv().getOrDefault("FARMER_SERVICE_URL","http://localhost:8082")).build();risk=WebClient.builder().baseUrl(System.getenv().getOrDefault("RISK_SERVICE_URL","http://localhost:8083")).build();}
record Request(String farmerEmail,String purpose,Double requestedAmount,Integer tenureMonths){}
@GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP","service","loan-service");}
@PostMapping("/assess") public ResponseEntity<?> assess(@RequestBody Request r){if(r.farmerEmail()==null||r.purpose()==null||r.requestedAmount()==null||r.requestedAmount()<=0||r.tenureMonths()==null||r.tenureMonths()<1||r.tenureMonths()>360)return ResponseEntity.badRequest().body(Map.of("error","Farmer email, purpose, positive amount and tenure (1–360 months) are required"));try{Map profile=farmer.get().uri("/api/farmers/{email}",r.farmerEmail()).retrieve().bodyToMono(Map.class).block();if(profile==null)return ResponseEntity.badRequest().body(Map.of("error","Farmer profile not found. Save the farmer profile first."));Map<String,Object> input=new HashMap<>();input.put("email",r.farmerEmail());input.put("purpose",r.purpose());input.put("requestedAmount",r.requestedAmount());input.put("tenureMonths",r.tenureMonths());input.put("landAcres",profile.get("landAcres"));input.put("crop",profile.get("primaryCrop"));input.put("season",profile.get("cropSeason"));input.put("annualIncome",profile.get("annualIncome"));input.put("existingDebt",profile.get("existingDebt"));input.put("latePayments",profile.get("latePayments"));input.put("onTimePayments",profile.get("onTimePayments"));input.put("expectedIncome",profile.get("expectedIncome"));Map assessment=risk.post().uri("/api/risk/assess").bodyValue(input).retrieve().bodyToMono(Map.class).block();LoanApplication l=new LoanApplication();l.farmerEmail=r.farmerEmail();l.purpose=r.purpose();l.requestedAmount=r.requestedAmount();l.tenureMonths=r.tenureMonths();l.score=((Number)assessment.get("score")).intValue();l.riskCategory=Objects.toString(assessment.get("category"));l.eligibleAmount=((Number)assessment.get("eligibleAmount")).doubleValue();l.recommendation=Objects.toString(assessment.get("recommendation"));l.factorsJson=mapper.writeValueAsString(assessment.get("factors"));repo.save(l);Map<String,Object> out=new LinkedHashMap<>(assessment);out.put("loanId",l.id);out.put("status",l.status);out.put("farmerEmail",l.farmerEmail);out.put("purpose",l.purpose);out.put("tenureMonths",l.tenureMonths);out.put("createdAt",l.createdAt);return ResponseEntity.ok(out);}catch(Exception e){return ResponseEntity.status(502).body(Map.of("error","Assessment service unavailable or farmer profile missing","detail",Objects.toString(e.getMessage(),"Unknown error")));}}
@GetMapping public List<LoanApplication> all(){return repo.findAllByOrderByCreatedAtDesc();}
@GetMapping("/farmer/{email}") public List<LoanApplication> byFarmer(@PathVariable String email){return repo.findByFarmerEmailIgnoreCaseOrderByCreatedAtDesc(email);}
@PatchMapping("/{id}/decision") public ResponseEntity<?> decision(@PathVariable Long id,@RequestBody Map<String,String> body){LoanApplication l=repo.findById(id).orElse(null);if(l==null)return ResponseEntity.notFound().build();String decision=Objects.toString(body.get("decision"),"").toUpperCase();if(!List.of("APPROVED","REJECTED","NEEDS_REVIEW").contains(decision))return ResponseEntity.badRequest().body(Map.of("error","Decision must be APPROVED, REJECTED or NEEDS_REVIEW"));l.status=decision;l.bankerNote=Objects.toString(body.get("note"),"");repo.save(l);return ResponseEntity.ok(l);}}
